(function () {
  var payload = $.payload || {};
  if (payload.input != null && typeof payload.input === 'object') {
    payload = payload.input;
  }

  var sourceIds = payload.OutFeeItemIdList || [];
  if (!Array.isArray(sourceIds)) {
    sourceIds = [sourceIds];
  }
  sourceIds = sourceIds
    .filter(function (id) { return id != null && String(id) !== ''; })
    .map(function (id) { return String(id); });

  var patientCode = payload.PatientCode != null ? String(payload.PatientCode) : '';
  var apiBaseUrl = payload.apiBaseUrl != null && String(payload.apiBaseUrl) !== ''
    ? String(payload.apiBaseUrl)
    : 'http://127.0.0.1:8807';
  if (apiBaseUrl.charAt(apiBaseUrl.length - 1) === '/') {
    apiBaseUrl = apiBaseUrl.substring(0, apiBaseUrl.length - 1);
  }
  var serviceProviderType = payload.ServiceProviderType != null
    ? String(payload.ServiceProviderType)
    : '';

  return {
    apiBaseUrl: apiBaseUrl,
    serviceProviderType: serviceProviderType,
    requestBody: {
      sourceIds: sourceIds,
      patientCode: patientCode
    }
  };
})()

(function () {
  return {
    code: '400',
    message: 'Unsupported ServiceProviderType: ' + ($.serviceProviderType || ''),
    data: null
  };
})()

(function () {
  function normalize(body) {
    if (!body) {
      return { code: '', message: '', data: null };
    }
    return {
      code: body.code != null ? String(body.code)
        : (body.returnCode != null ? String(body.returnCode) : ''),
      message: body.message || body.msg || body.errorMessage || '',
      data: body.data != null ? body.data : (body.result != null ? body.result : null)
    };
  }

  var selectedCase = String($.selectedCase != null ? $.selectedCase : '');
  var requestBody = $.requestBody || null;
  var responseBody = null;
  if (selectedCase === 'LIS') {
    responseBody = $.lisResponseBody;
  } else if (selectedCase === 'PACS') {
    responseBody = $.pacsResponseBody;
  } else {
    return {
      serviceProviderType: selectedCase,
      requestBody: null,
      response: $.unsupportedResponse || normalize(null)
    };
  }

  return {
    serviceProviderType: selectedCase,
    requestBody: requestBody,
    response: normalize(responseBody)
  };
})()
